// ListNode 由评测环境提供，请勿重复定义
class Solution {
public:
    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
        // 逐位相加并处理进位；用 long long 累加避免溢出
        ListNode dummy(0);
        ListNode* cur = &dummy;
        long long carry = 0;
        while (l1 || l2 || carry) {
            long long s = carry;
            if (l1) { s += l1->val; l1 = l1->next; }
            if (l2) { s += l2->val; l2 = l2->next; }
            cur->next = new ListNode((int)(s % 10));
            cur = cur->next;
            carry = s / 10;
        }
        return dummy.next;
    }
};

