class Solution {
public:
    double findMedianSortedArrays(vector<int>& nums1, vector<int>& nums2) {
        vector<int> A = nums1, B = nums2;
        if (A.size() > B.size()) swap(A, B);
        int m = (int)A.size(), n = (int)B.size();
        int lo = 0, hi = m;
        int total_left = (m + n + 1) / 2;
        while (lo <= hi) {
            int i = (lo + hi) / 2;
            int j = total_left - i;
            if (i < m && A[i] < B[j - 1]) {
                lo = i + 1;
            } else if (i > 0 && A[i - 1] > B[j]) {
                hi = i - 1;
            } else {
                int max_left;
                if (i == 0) max_left = B[j - 1];
                else if (j == 0) max_left = A[i - 1];
                else max_left = max(A[i - 1], B[j - 1]);
                if ((m + n) % 2 == 1) return (double)max_left;
                int min_right;
                if (i == m) min_right = B[j];
                else if (j == n) min_right = A[i];
                else min_right = min(A[i], B[j]);
                return (max_left + min_right) / 2.0;
            }
        }
        return 0.0;
    }
};

