// ListNode 由评测环境提供，请勿重复定义
class Solution {
public:
    ListNode* removeNthFromEnd(ListNode* head, int n) {
        // 快指针先走 n 步，再与慢指针同步走，慢指针指向待删节点前驱
        ListNode dummy(0);
        dummy.next = head;
        ListNode* fast = &dummy;
        ListNode* slow = &dummy;
        for (int i = 0; i < n; i++) fast = fast->next;
        while (fast->next) {
            fast = fast->next;
            slow = slow->next;
        }
        slow->next = slow->next->next;
        return dummy.next;
    }
};

