class Solution {
public:
    ListNode* reverseKGroup(ListNode* head, int k) {
        // 反转区间 [a, b)，返回新头
        auto rev = [](ListNode* a, ListNode* b) -> ListNode* {
            ListNode* pre = nullptr;
            while (a != b) {
                ListNode* nxt = a->next;
                a->next = pre;
                pre = a;
                a = nxt;
            }
            return pre;
        };
        ListNode dummy(0);
        dummy.next = head;
        ListNode* pre = &dummy;
        while (true) {
            ListNode* tail = pre;
            for (int i = 0; i < k; i++) {
                tail = tail->next;
                if (!tail) return dummy.next;  // 剩余不足 k 个，保持原序
            }
            ListNode* nxt = tail->next;
            ListNode* first = pre->next;
            pre->next = rev(first, tail->next);
            first->next = nxt;
            pre = first;
        }
    }
};

