class Solution {
public:
    int trap(vector<int>& height) {
        int n = (int)height.size();
        int l = 0, r = n - 1, lmax = 0, rmax = 0;
        long long ans = 0;
        while (l <= r) {
            if (lmax <= rmax) {
                lmax = max(lmax, height[l]);
                ans += lmax - height[l];
                l++;
            } else {
                rmax = max(rmax, height[r]);
                ans += rmax - height[r];
                r--;
            }
        }
        return (int)ans;
    }
};

