    vector<vector<int>> permute(vector<int>& nums) {
        vector<vector<int>> res;
        int n = nums.size();
        vector<bool> used(n, false);
        vector<int> path;
        function<void()> dfs = [&]() {
            if ((int)path.size() == n) { res.push_back(path); return; }
            for (int i = 0; i < n; i++) {  // 按下标递增顺序尝试，保证确定性输出
