class Solution {
public:
    int maxProduct(vector<int>& nums) {
        // 同时维护以当前元素结尾的最大/最小乘积，中间量用 long long 防溢出
        long long cur_max = nums[0], cur_min = nums[0], best = nums[0];
        for (int i = 1; i < (int)nums.size(); i++) {
            long long v = nums[i];
            if (v < 0) swap(cur_max, cur_min);
            cur_max = max(v, cur_max * v);
            cur_min = min(v, cur_min * v);
            best = max(best, cur_max);
        }
        return (int)best;
    }
};

