public:
    int findKthLargest(vector<int>& nums, int k) {
        priority_queue<int, vector<int>, greater<int>> pq;  // 大小为 k 的小根堆
        for (int i = 0; i < k; i++) pq.push(nums[i]);
        for (int i = k; i < (int)nums.size(); i++) {
            if (nums[i] > pq.top()) { pq.pop(); pq.push(nums[i]); }
        }
        return pq.top();
    }
};

