from collections import deque

def maxSlidingWindow(nums, k):
    # 单调递减队列，队首即当前窗口最大值
    q = deque()
    res = []
    for i, v in enumerate(nums):
        while q and nums[q[-1]] <= v:
            q.pop()
        q.append(i)
        if q[0] <= i - k:
            q.popleft()
        if i >= k - 1:
            res.append(nums[q[0]])
    return res

