class Solution {
public:
    int pathSum(TreeNode* root, int targetSum) {
        unordered_map<long long, int> pre;
        pre[0] = 1;
        int ans = 0;
        function<void(TreeNode*, long long)> dfs = [&](TreeNode* node, long long cur) {
            if (!node) return;
            cur += node->val;
            ans += pre[cur - targetSum];
            pre[cur]++;
            dfs(node->left, cur);
            dfs(node->right, cur);
            pre[cur]--;
        };
        dfs(root, 0);
        return ans;
    }
};

