    TreeNode* root = new TreeNode(stoi(arr[0]));
    queue<TreeNode*> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < arr.size()) {
        TreeNode* cur = q.front();
        q.pop();
        if (i < arr.size() && arr[i] != "null") { cur->left = new TreeNode(stoi(arr[i])); q.push(cur->left); }
        i++;
        if (i < arr.size() && arr[i] != "null") { cur->right = new TreeNode(stoi(arr[i])); q.push(cur->right); }
        i++;
    }
    return root;
}

int best = 0;

int depth(TreeNode* node) {
    if (!node) return 0;
    int l = depth(node->left);
    int r = depth(node->right);
    best = max(best, l + r);
    return 1 + max(l, r);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<string> arr(n);
    for (int i = 0; i < n; i++) cin >> arr[i];
    best = 0;
    depth(build(arr));
    cout << best << '\n';
    return 0;
}

