def subarraySum(nums, k):
    cnt = {0: 1}
    pre = 0
    ans = 0
    for x in nums:
        pre += x
        ans += cnt.get(pre - k, 0)
        cnt[pre] = cnt.get(pre, 0) + 1
    return ans

