from collections import deque


def orangesRotting(grid):
    m, n = len(grid), len(grid[0])
    q = deque()
    fresh = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == '2':
                q.append((i, j))
            elif grid[i][j] == '1':
                fresh += 1
    minutes = 0
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    # 多源 BFS，按层扩散，一层代表一分钟
    while q and fresh > 0:
        for _ in range(len(q)):
            i, j = q.popleft()
            for di, dj in dirs:
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == '1':
                    grid[ni][nj] = '2'
                    fresh -= 1
                    q.append((ni, nj))
        minutes += 1
    return -1 if fresh > 0 else minutes

